// ---------------------------------------------------------------------------
// Frame chrome — a frame's per-frame editor decorations, all stored as `data-*`
// on the frame `<g>` so they round-trip the history/save snapshot:
//   • layout grid (data-grid-*), • edge rulers (data-frame-rulers),
//   • export targets (data-export-targets — the files a frame produces).
// The on-canvas drawing is derived chrome regenerated by the frame renderer, so
// none of this leaks into exported artwork.
//
// Extracted from AppState as a collaborator (see EffectsManager / MarkersManager):
// it reaches AppState only through the FrameChromeHost seam. syncArtboards() keeps
// the derived artboards cache (which mirrors grid config) in step after a change.
// ---------------------------------------------------------------------------

import type { FrameGrid, ExportTarget } from './types';

/** Effective line spacing of a frame grid at the frame's CURRENT size. px mode is
 *  uniform `size` on both axes; divisions mode derives spacing from the dims
 *  (width/cols, height/rows, split into `subdivisions` minor cells) — which is
 *  what makes a divisions grid stay "N divisions" when the frame resizes.
 *  Single source of truth for the renderer and grid-snapping. */
export function gridSteps(g: FrameGrid, w: number, h: number): { sx: number; sy: number } {
  if (g.mode === 'divisions') {
    const sub = Math.max(1, g.subdivisions);
    return { sx: w / (Math.max(1, g.cols) * sub), sy: h / (Math.max(1, g.rows) * sub) };
  }
  return { sx: g.size, sy: g.size };
}

/** Frame-size-aware default grid: a divisions grid whose col/row counts keep the
 *  cells roughly square (near TARGET px) instead of a flat 8×8 that stretches on
 *  wide/tall frames. Counts round to the nearest EVEN number (≥2) so the frame's
 *  centre axes always land on a gridline (the #109 even-division property, now
 *  expressed in divisions mode where the COUNT survives resize). Falls back to 8
 *  on a zero/unknown dimension. Callers set `snap`/`visible` to taste. */
export function defaultFrameGrid(width: number, height: number): FrameGrid {
  const TARGET = 64; // desired cell size, frame-local px
  const evenCount = (dim: number) => (dim > 0 ? Math.max(2, Math.round(dim / TARGET / 2) * 2) : 8);
  return {
    mode: 'divisions', size: 8,
    cols: evenCount(Math.round(width)),
    rows: evenCount(Math.round(height)),
    subdivisions: 4, color: '#7f8fa6', visible: true, snap: true,
  };
}

export interface FrameChromeHost {
  /** The frame element for a shape id, or null if it isn't a frame. */
  frameElement(id: string): SVGElement | null;
  /** Re-derive the artboards cache (grid config is mirrored there). */
  syncArtboards(): void;
  saveHistory(): void;
  onChange(): void;
}

export class FrameChromeManager {
  private host: FrameChromeHost;
  constructor(host: FrameChromeHost) { this.host = host; }

  /** A frame element's grid config (attrs are the source of truth), or null.
   *  Public so AppState.frameToArtboard can mirror it into the artboards cache. */
  gridOf(el: SVGElement): FrameGrid | null {
    if (!el.hasAttribute('data-grid')) return null;
    const count = (attr: string) => Math.max(1, Math.round(parseFloat(el.getAttribute(attr) ?? '4') || 4));
    return {
      // Legacy docs have no data-grid-mode → 'px', the original behavior.
      mode: el.getAttribute('data-grid-mode') === 'divisions' ? 'divisions' : 'px',
      size: Math.max(1, parseFloat(el.getAttribute('data-grid-size') ?? '8') || 8),
      cols: count('data-grid-cols'),
      rows: count('data-grid-rows'),
      subdivisions: Math.max(1, Math.round(parseFloat(el.getAttribute('data-grid-subdiv') ?? '1') || 1)),
      color: el.getAttribute('data-grid-color') || '#7f8fa6',
      visible: el.getAttribute('data-grid-hidden') !== '1',
      snap: el.getAttribute('data-grid-snap') === '1',
    };
  }

  /** A frame's grid config by id, or null if it has none. */
  getGrid(id: string): FrameGrid | null {
    const el = this.host.frameElement(id);
    return el ? this.gridOf(el) : null;
  }

  /** Set (or clear, with null) a frame's grid. One undo step when `record`. */
  setGrid(id: string, grid: FrameGrid | null, record = true): void {
    const el = this.host.frameElement(id);
    if (!el) return;
    if (!grid) {
      for (const a of ['data-grid', 'data-grid-mode', 'data-grid-size', 'data-grid-cols', 'data-grid-rows', 'data-grid-subdiv', 'data-grid-color', 'data-grid-hidden', 'data-grid-snap']) el.removeAttribute(a);
    } else {
      el.setAttribute('data-grid', '1');
      // px mode carries no mode attr, matching legacy docs exactly.
      if (grid.mode === 'divisions') el.setAttribute('data-grid-mode', 'divisions');
      else el.removeAttribute('data-grid-mode');
      el.setAttribute('data-grid-size', String(Math.max(1, grid.size)));
      el.setAttribute('data-grid-cols', String(Math.max(1, Math.round(grid.cols))));
      el.setAttribute('data-grid-rows', String(Math.max(1, Math.round(grid.rows))));
      el.setAttribute('data-grid-subdiv', String(Math.max(1, Math.round(grid.subdivisions))));
      el.setAttribute('data-grid-color', grid.color);
      if (grid.visible) el.removeAttribute('data-grid-hidden'); else el.setAttribute('data-grid-hidden', '1');
      if (grid.snap) el.setAttribute('data-grid-snap', '1'); else el.removeAttribute('data-grid-snap');
    }
    this.host.syncArtboards();
    if (record) this.host.saveHistory();
    this.host.onChange();
  }

  getRulers(id: string): boolean {
    return this.host.frameElement(id)?.getAttribute('data-frame-rulers') === '1';
  }

  setRulers(id: string, on: boolean, record = true): void {
    const el = this.host.frameElement(id);
    if (!el) return;
    if (on) el.setAttribute('data-frame-rulers', '1'); else el.removeAttribute('data-frame-rulers');
    this.host.syncArtboards();
    if (record) this.host.saveHistory();
    this.host.onChange();
  }

  /** A frame's export list — the files to produce when it's exported (one logo →
   *  many platform assets). Stored as JSON in data-export-targets so it round-trips
   *  through the history/save snapshot. Falls back to a migrated single target (old
   *  data-export-format/scale) or a sensible default, so there's always ≥1 target. */
  getExportTargets(id: string): ExportTarget[] {
    const el = this.host.frameElement(id);
    if (!el) return [];
    const base = this.baseName(el);
    const raw = el.getAttribute('data-export-targets');
    if (raw) {
      try {
        const arr = JSON.parse(raw);
        if (Array.isArray(arr)) {
          const clean = arr.map((t) => this.coerceTarget(t, base)).filter(Boolean) as ExportTarget[];
          if (clean.length) return clean;
        }
      } catch { /* fall through to migration/default */ }
    }
    // Migrate the old single-setting model, else a default SVG target.
    const legacy = el.getAttribute('data-export-format');
    if (legacy) {
      const fmt = legacy === 'png' || legacy === 'jpg' ? legacy : 'svg';
      const scale = Math.min(4, Math.max(1, parseFloat(el.getAttribute('data-export-scale') ?? '1') || 1));
      return [{ format: fmt, name: base, scale }];
    }
    return [{ format: 'svg', name: base, scale: 1 }];
  }

  setExportTargets(id: string, targets: ExportTarget[], record = true): void {
    const el = this.host.frameElement(id);
    if (!el) return;
    el.setAttribute('data-export-targets', JSON.stringify(targets));
    el.removeAttribute('data-export-format'); // supersede the legacy single-setting attrs
    el.removeAttribute('data-export-scale');
    if (record) this.host.saveHistory();
    this.host.onChange();
  }

  /** A frame's background colour, or null when transparent. The `.frame-bg` rect's
   *  `fill` is the store (it round-trips in the snapshot); 'none' reads as null. */
  getBackground(id: string): string | null {
    const bg = this.host.frameElement(id)?.querySelector(':scope > rect.frame-bg') as SVGRectElement | null;
    const fill = bg?.getAttribute('fill');
    return (!fill || fill === 'none') ? null : fill;
  }

  /** Set a frame's background fill (null / transparent clears it back to none). */
  setBackground(id: string, color: string | null, record = true): void {
    const bg = this.host.frameElement(id)?.querySelector(':scope > rect.frame-bg') as SVGRectElement | null;
    if (!bg) return;
    bg.setAttribute('fill', color && color !== 'transparent' ? color : 'none');
    if (record) this.host.saveHistory();
    this.host.onChange();
  }

  private baseName(el: SVGElement): string {
    const raw = (el.getAttribute('data-name') || 'frame').trim();
    return raw.replace(/[<>:"/\\|?*]/g, '_').replace(/\s+/g, '-') || 'frame';
  }

  private coerceTarget(t: any, base: string): ExportTarget | null {
    if (!t || typeof t !== 'object') return null;
    const format: ExportTarget['format'] =
      ['svg', 'png', 'jpg', 'bmp', 'gif', 'tiff'].includes(t.format) ? t.format : 'svg';
    const num = (v: any) => (Number.isFinite(v) && v > 0 ? Math.round(v) : undefined);
    const out: ExportTarget = {
      format,
      name: (typeof t.name === 'string' && t.name.trim()) ? t.name.trim() : base,
      scale: Math.min(8, Math.max(0.1, Number.isFinite(t.scale) && t.scale > 0 ? t.scale : 1)),
      width: num(t.width),
      height: num(t.height),
    };
    // Per-format options — preserve only meaningful, valid values for the format.
    if (format === 'svg') {
      if (t.textMode === 'keep' || t.textMode === 'outline' || t.textMode === 'embed') out.textMode = t.textMode;
      if (typeof t.bake === 'boolean') out.bake = t.bake;
    }
    if (format === 'jpg' && Number.isFinite(t.quality)) {
      out.quality = Math.min(1, Math.max(0.01, t.quality));
    }
    if (typeof t.background === 'string' && (t.background === 'transparent' || /^#[0-9a-fA-F]{3,8}$/.test(t.background))) {
      out.background = t.background;
    }
    if (t.bounds === 'paths') out.bounds = 'paths';
    return out;
  }
}
